head.b:skin:
/* Reset all Blogger layout, sidebars, headers, footers & attribution */
*, *::before, *::after {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}
html, body {
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
  height: 100% !important;
  overflow: hidden !important;
  background-color: #0f0f0f !important;
}
#appFrame {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border: 0;
  outline: 0;
  display: block;
  z-index: 9999;
}
.header, .footer, .sidebar, .widget, .blog-pager, .post-feeds, #b-navbar, 
.status-msg-wrap, .attribution, .quickedit, #navbar, .navbar {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  height: 0 !important;
  width: 0 !important;
}

